    """Restore color-2 occlusions using the square image's dihedral symmetry."""
    h, w = len(grid), len(grid[0])
    if h != w:
        raise ValueError("Expected a square grid")
    n = h
    out = [row[:] for row in grid]

    def orbit(r, c):
        # All eight rotations/reflections of a square coordinate.
        return {
            (r, c), (c, n - 1 - r), (n - 1 - r, n - 1 - c), (n - 1 - c, r),
            (r, n - 1 - c), (n - 1 - r, c), (c, r), (n - 1 - c, n - 1 - r),
        }

    for r in range(n):
        for c in range(n):
            if grid[r][c] == 2:
                known = {grid[rr][cc] for rr, cc in orbit(r, c) if grid[rr][cc] != 2}
                if len(known) != 1:
                    raise ValueError(f"Cannot uniquely restore cell {(r, c)}: {known}")
                out[r][c] = known.pop()
    return out
